// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        ancillaryData = ancillaryData.length > 512 ? slice(ancillaryData, 0, 512) : ancillaryData;

        int256 price;
        bool ok = true;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 p) {
            price = p;
        } catch {
            ok = false;
        }

        assertTrue(ok && price == int256(0));
    }

    function slice(bytes memory data, uint256 start, uint256 len) internal pure returns (bytes memory) {
        if (data.length <= start) return new bytes(0);
        uint256 available = data.length - start;
        uint256 take = available < len ? available : len;
        bytes memory out = new bytes(take);
        for (uint256 i = 0; i < take; i++) {
            out[i] = data[start + i];
        }
        return out;
    }
}
